import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"00-2 手把手部署第一个智能合约（Remix）","description":"","frontmatter":{},"headers":[],"relativePath":"00-start/environment.md","filePath":"00-start/environment.md","lastUpdated":1791601077000}'),e={name:"00-start/environment.md"};function r(l,s,o,d,p,h){return i(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="_00-2-手把手部署第一个智能合约-remix" tabindex="-1">00-2 手把手部署第一个智能合约（Remix） <a class="header-anchor" href="#_00-2-手把手部署第一个智能合约-remix" aria-label="Permalink to &quot;00-2 手把手部署第一个智能合约（Remix）&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：你将在浏览器里亲手创建一个“计数器”：从 0 加到 1，再加到 2。全程使用 Remix 提供的虚拟账户，不需要注册交易所、不需要 MetaMask，也不花真钱。</p><p><strong>预计用时</strong>：初次操作约 30～50 分钟。页面可能随 Remix 更新略有变化，按<strong>功能名称</strong>找按钮即可。</p></blockquote><h2 id="这节课最终会看到什么" tabindex="-1">这节课最终会看到什么 <a class="header-anchor" href="#这节课最终会看到什么" aria-label="Permalink to &quot;这节课最终会看到什么&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>刚部署：</span></span>
<span class="line"><span>number = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一次点击 increment：</span></span>
<span class="line"><span>number = 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二次点击 increment：</span></span>
<span class="line"><span>number = 2</span></span></code></pre></div><p>它看起来很简单，但会串起五个知识点：<strong>源码 → 编译 → 部署 → 读取状态 → 发送修改交易</strong>。</p><h2 id="第-1-步-打开-remix-并认识界面" tabindex="-1">第 1 步：打开 Remix 并认识界面 <a class="header-anchor" href="#第-1-步-打开-remix-并认识界面" aria-label="Permalink to &quot;第 1 步：打开 Remix 并认识界面&quot;">​</a></h2><p>在浏览器打开 <a href="https://remix.ethereum.org/" target="_blank" rel="noreferrer">Remix IDE 官方网站</a>。</p><p>先不要连接钱包，也不要选主网。如果看到欢迎页面，可关闭引导进入编辑器。</p><p>你重点认识三块功能，通常在左侧工具栏：</p><ol><li><strong>File Explorer（文件管理器）</strong>：新建和编辑 Solidity 文件。</li><li><strong>Solidity Compiler（编译器）</strong>：把 Solidity 源码编译成字节码和 ABI。</li><li><strong>Deploy &amp; Run Transactions（部署和运行）</strong>：选择虚拟环境、账户，部署并调用函数。</li></ol><blockquote><p>不需要记住图标长什么样。编辑器升级后图标位置可能变化，看英文工具名更可靠。</p></blockquote><h2 id="第-2-步-新建-counter-sol-文件" tabindex="-1">第 2 步：新建 Counter.sol 文件 <a class="header-anchor" href="#第-2-步-新建-counter-sol-文件" aria-label="Permalink to &quot;第 2 步：新建 Counter.sol 文件&quot;">​</a></h2><p>在 File Explorer 中新建文件，名字<strong>必须包含后缀 <code>.sol</code></strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Counter.sol</span></span></code></pre></div><p>删除文件里的示例代码，将以下内容<strong>完整复制</strong>进去：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// SPDX-License-Identifier: MIT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pragma</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> solidity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ^0.8.24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">contract</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Counter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    event</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Increased</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> current</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> increment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        number </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        emit</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Increased</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, number);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="暂时不懂代码-按行理解就行" tabindex="-1">暂时不懂代码？按行理解就行 <a class="header-anchor" href="#暂时不懂代码-按行理解就行" aria-label="Permalink to &quot;暂时不懂代码？按行理解就行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代码</th><th>白话解释</th></tr></thead><tbody><tr><td><code>// SPDX-License-Identifier: MIT</code></td><td>告诉工具源码使用什么许可证</td></tr><tr><td><code>pragma solidity ^0.8.24;</code></td><td>要求使用兼容 0.8.24 的 0.8.x 编译器</td></tr><tr><td><code>contract Counter { ... }</code></td><td>声明一个叫 Counter 的合约</td></tr><tr><td><code>uint256 public number;</code></td><td>存一个不能是负数的整数，名称叫 number，初始为 0</td></tr><tr><td><code>event Increased(...)</code></td><td>定义一条“数字增加了”的日志格式</td></tr><tr><td><code>function increment() external</code></td><td>提供一个供外部调用的“加一”函数</td></tr><tr><td><code>number += 1;</code></td><td>把链上存储的数字加 1</td></tr><tr><td><code>emit Increased(...)</code></td><td>执行时发出事件，记录是谁调用和新数字</td></tr><tr><td><code>msg.sender</code></td><td>当前这次调用的直接发起地址</td></tr></tbody></table><p><code>public</code> 会自动生成一个读数用的 <strong>number()</strong> 函数，<strong>不代表别人可以直接赋值覆盖 number</strong>。</p><h2 id="第-3-步-编译" tabindex="-1">第 3 步：编译 <a class="header-anchor" href="#第-3-步-编译" aria-label="Permalink to &quot;第 3 步：编译&quot;">​</a></h2><ol><li>点击左侧 <strong>Solidity Compiler</strong>。</li><li>选择与 <code>^0.8.24</code> 兼容的 0.8.x 编译器（例如 0.8.24；不要选 0.9.x）。</li><li>点击 <strong>Compile Counter.sol</strong>（或打开自动编译）。</li><li>成功时没有红色编译错误；你应能在编译结果中找到 Counter 合约。</li></ol><p>这里的“编译”类似 Python 项目准备运行，但 Solidity 是将源码转换成 EVM 可执行字节码，同时生成 ABI（调用接口说明）。</p><p><strong>常见报错：</strong></p><ul><li><code>Source file requires different compiler version</code>：编译器不匹配，调整版本。</li><li><code>ParserError</code>：复制时漏了分号、括号或多了奇怪字符，核对整段代码。</li><li>找不到 Counter：可能编译了其他文件，先在编辑器打开 Counter.sol 再编译。</li></ul><h2 id="第-4-步-在本地虚拟链部署" tabindex="-1">第 4 步：在本地虚拟链部署 <a class="header-anchor" href="#第-4-步-在本地虚拟链部署" aria-label="Permalink to &quot;第 4 步：在本地虚拟链部署&quot;">​</a></h2><ol><li>点击 <strong>Deploy &amp; Run Transactions</strong>。</li><li>在 <strong>Environment</strong> 一栏选择名称包含 <strong>Remix VM</strong> 的虚拟环境。不同版本可能显示为 Remix VM (Cancun / Shanghai 等)。</li><li><strong>不要</strong>选择 Injected Provider、连接钱包或任何主网。</li><li>观察 <strong>Account</strong>：Remix 为你准备了一组虚拟账户和测试余额。</li><li>在 <strong>Contract</strong> 下拉框中选择 <strong>Counter</strong>。</li><li>点击 <strong>Deploy</strong>。</li></ol><p>如果成功，页面下方的 <strong>Deployed Contracts</strong> 区域会出现类似 <code>COUNTER AT 0x...</code> 的可展开条目。这就是<strong>部署出的合约实例</strong>；<code>0x...</code> 是它在虚拟链上的地址，不是你的用户账号。</p><p><strong>你刚刚做了什么？</strong> 部署本身也是一次状态改变操作，会执行一笔虚拟交易，在虚拟链中创建合约实例。</p><h2 id="第-5-步-先-读取-再-修改" tabindex="-1">第 5 步：先“读取”，再“修改” <a class="header-anchor" href="#第-5-步-先-读取-再-修改" aria-label="Permalink to &quot;第 5 步：先“读取”，再“修改”&quot;">​</a></h2><p>展开 Deployed Contracts 下的 Counter：</p><p><strong>实验 A：读取</strong></p><ol><li>找到 <strong>number</strong> 按钮（颜色可能因 Remix 版本而不同）。</li><li>点击后查看返回值：应该是 <code>0</code>。</li><li>留意终端/控制台的调用记录：这类读取一般不需要提交链上交易。</li></ol><p><strong>实验 B：修改</strong></p><ol><li>找到 <strong>increment</strong> 按钮并点击一次。</li><li>Remix 会在虚拟链里执行一次交易。</li><li>再点击 <strong>number</strong>，应该看到 <code>1</code>。</li><li>再点一次 <strong>increment</strong>，再读 number，应该是 <code>2</code>。</li></ol><p>为什么读取按钮和写入按钮行为不同？因为数字真正存到了合约的链上状态。<strong>读可以本地查询，改就需要执行交易。</strong></p><h2 id="第-6-步-学会看交易信息和事件" tabindex="-1">第 6 步：学会看交易信息和事件 <a class="header-anchor" href="#第-6-步-学会看交易信息和事件" aria-label="Permalink to &quot;第 6 步：学会看交易信息和事件&quot;">​</a></h2><p>在 Remix 的终端 / Transactions 记录中找到刚才的 increment：</p><ul><li><strong>交易哈希（transaction hash）</strong>：这笔交易的标识。</li><li><strong>from</strong>：调用者的虚拟地址。</li><li><strong>to</strong>：Counter 合约地址。</li><li><strong>status</strong>：交易执行成功还是失败。</li><li><strong>gas used</strong>：此次实际执行使用的 Gas 量。</li><li><strong>logs / event</strong>：如果 Remix 展示事件，能找到 <code>Increased</code> 及 sender、current。</li></ul><p>不要死记某个 Gas 数字，因为编译设置和执行环境不同可能有差异。</p><h2 id="第-7-步-换一个账户再试" tabindex="-1">第 7 步：换一个账户再试 <a class="header-anchor" href="#第-7-步-换一个账户再试" aria-label="Permalink to &quot;第 7 步：换一个账户再试&quot;">​</a></h2><p>在 Deploy &amp; Run 的 Account 下拉框切换到另一个虚拟地址，再点一次 increment。读取 number 应该变成 3。</p><p>你会发现：<strong>这个合约并没有限制谁可以点击 increment</strong>。所有调用者都可以把数字加一。下一章我们会加上 owner（所有者）权限，让你亲眼看到没有权限时交易失败。</p><h2 id="新手故障排查" tabindex="-1">新手故障排查 <a class="header-anchor" href="#新手故障排查" aria-label="Permalink to &quot;新手故障排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>遇到的现象</th><th>通常是什么原因</th><th>怎样排查</th></tr></thead><tbody><tr><td>没有 Deploy 按钮或合约可选</td><td>还没编译，或编译了别的文件</td><td>回 Compiler 编译 Counter.sol</td></tr><tr><td>部署后 number 不显示</td><td>没展开 Deployed Contracts</td><td>展开对应 Counter 条目</td></tr><tr><td>number 一直为 0</td><td>点的是读取而不是 increment，或操作了另一个实例</td><td>先点 increment，再读同一合约实例</td></tr><tr><td>刷新后合约实例不见了</td><td>Remix VM 的工作状态可能已重置</td><td>重新选择 Remix VM、编译、部署；切勿把 VM 当持久主网</td></tr><tr><td>浏览器提示连接真实钱包</td><td>误选 Injected Provider</td><td>切回 Remix VM</td></tr><tr><td>红色 revert / error</td><td>调用未成功</td><td>先看终端错误，不要把“按钮点了”当作成功</td></tr></tbody></table><h2 id="挑战题-先做-再看答案" tabindex="-1">挑战题（先做，再看答案） <a class="header-anchor" href="#挑战题-先做-再看答案" aria-label="Permalink to &quot;挑战题（先做，再看答案）&quot;">​</a></h2><p><strong>任务 1</strong>：把函数改名为 <code>increaseByTwo</code>，让它每次加 2。重新编译、重新部署，并验证 0 → 2 → 4。</p><p><strong>任务 2</strong>：想让 number 从 4 变回 0，仅靠当前合约的按钮能做到吗？</p><details><summary>参考答案</summary><ol><li>将函数名改为 <code>increaseByTwo</code>，并把 <code>number += 1</code> 改为 <code>number += 2</code>。重新编译后<strong>重新部署</strong>；旧实例并不会自动换成新代码。</li><li>不行。当前合约只提供加一函数，没有 reset 函数；部署者也不能越过合约规则直接修改链上状态。后面的 Solidity 课会添加受 owner 控制的 reset。</li></ol></details><h2 id="进阶-准备本地-foundry-本课可以先跳过" tabindex="-1">进阶：准备本地 Foundry（本课可以先跳过） <a class="header-anchor" href="#进阶-准备本地-foundry-本课可以先跳过" aria-label="Permalink to &quot;进阶：准备本地 Foundry（本课可以先跳过）&quot;">​</a></h2><p>如果已经完成 Remix 实验，才需要考虑命令行工具：</p><ul><li><strong>forge</strong>：编译与测试 Solidity 工程。</li><li><strong>anvil</strong>：在本机启动一个用于实验的以太坊开发节点。</li><li><strong>cast</strong>：命令行查询、编码及调用链上数据。</li></ul><p>推荐 Linux、macOS 或 Windows 的 WSL2 环境，安装方式以 <a href="https://getfoundry.sh/introduction/installation/" target="_blank" rel="noreferrer">Foundry 官方说明</a> 为准，不执行不明脚本。</p><p>安装完成后在终端逐个验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">anvil</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>在<strong>本仓库根目录</strong>下运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/foundry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span></span></code></pre></div><p>如果提示 <code>forge: command not found</code>，说明 Foundry 未安装成功、未加载到 PATH 或终端未重新打开。不要用真实钱包私钥“排查”工具问题。</p><h2 id="本课验收" tabindex="-1">本课验收 <a class="header-anchor" href="#本课验收" aria-label="Permalink to &quot;本课验收&quot;">​</a></h2><p>做到以下四点再继续：<strong>你亲手完成了部署</strong>；看到了 0 → 1 → 2；找到了调用记录；能解释“读数不用写入交易，加一需要交易”。</p><ul><li><a href="/00-start/backend-map">下一课：把 Flask、数据库和链上程序对应起来</a></li><li><a href="/00-start/glossary">不认识术语？查词典</a></li><li><a href="/00-start/troubleshooting">遇到 Remix 错误？按现象排查</a></li><li><a href="/00-start/troubleshooting">遇到 Remix 错误？按现象排查</a></li></ul>`,60)])])}const k=t(e,[["render",r]]);export{g as __pageData,k as default};
